import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"42、【益】 震下巽上","description":"周易尚氏學 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"周易尚氏學 - 42、【益】 震下巽上"},"headers":[],"relativePath":"classics/shangshi/047.md","filePath":"classics/shangshi/047.md"}'),s={name:"classics/shangshi/047.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><p>貞我悔彼。以彼之陽。下來益我。故曰益也。歸藏曰誠。說文。誠和也。書召誥。其丕能誠於小民。注亦訓誠為和。風雷同聲相應。和之至也。是周易以陽爻上下言。故曰益。歸藏合上下卦言曰誠也。利有攸往。謂五。五既中且正。傳所謂中正有慶也。利涉大川謂初。坤大川。震為舟。初陽遇陰而通。故曰利涉。傳所謂術道乃行也。</p><p>彖曰。益。損上益下。民說無疆。自上下下。其道大光。利有攸往。中正有慶。利涉大川。木道乃行。益動而巽。曰進無疆。天施地生。其益無方。凡益之道。與時偕行。</p><p>坤為民。震為樂。故曰民說。坤為廣。故曰無疆。否四來居下卦之下。故曰自上下下。震為玄黃。故曰大光。利有攸往。中正有慶。謂五。利涉大川。木道乃行。謂初。震為舟故曰木。古刳木為舟。故謂舟為木。。渙曰乘木有功。中孚曰乘木舟虛。皆以木為舟。利涉大川。故曰木道乃行。言舟行水上。舟楫之利用溥也。此純釋利涉之義。坤為水。震為舟。故曰木曰行。程子不知本即為舟。改木為益。野文之害。至斯而極。陽自外來。故曰天施。震為生。坤為地。故曰地生。益者否之終。泰之始。太玄雲。巳用則賤。當時則貴。艮為時。與時偕行者。言時而當益。不能不益也。</p><p>象曰。風雷益。君子以見喜則遷。有過則改。</p><p>乾力善。坤為過。乾來初。得值得民。是遷善也。乾來初成震。坤象滅。是改過也。故學易之君子法之。</p><p>初九。利用為大作。元吉元咎。</p><p>虞翻雲。大作謂耕播未來之利。按虞書。平秩東作。注歲起於東。而始就耕。謂之東作。禹貢恆衛既從。大陸既作。注二水巳治。從其故道。大陸之地已可耕作。是作即耕也。震為春。為耕。至春民盡耕。故曰大作。陽遇陰故利。乾元通。故元吉無咎。</p><h3 id="象曰。元吉無咎。下不厚事也。" tabindex="-1">象曰。元吉無咎。下不厚事也。 <a class="header-anchor" href="#象曰。元吉無咎。下不厚事也。" aria-label="Permalink to “象曰。元吉無咎。下不厚事也。”">​</a></h3><p>震健而決躁。故左氏以為射。言其速也。厚餘也。行速故無餘事。坤為事。言初雖在下。往利無阻。事無積滯。仍利涉大川之意也。</p><p>六二。或益之十朋之龜。弗克違。永貞吉。王用亨於帝吉。</p><p>艮為龜為朋友。坤數十。故曰十朋之龜。二應在五。五又故以十朋之龜益二也。二得陽應。故曰弗克違。二當位。故永貞於二吉。震為帝。王謂五。震為祭祀。故曰享。王用享於帝吉者。言五應二。則二吉也。</p><h3 id="象曰。或益之。自外來也。" tabindex="-1">象曰。或益之。自外來也。 <a class="header-anchor" href="#象曰。或益之。自外來也。" aria-label="Permalink to “象曰。或益之。自外來也。”">​</a></h3><p>外謂九五。恐人疑為初。</p><p>六三。益之用凶事。無咎。有孚中行。告公用圭。</p><p>三居坤中。坤為兇。為事。益之用凶事。言上來益三。為五所阻。大畜初九所謂有厲也。故曰凶事。二三四陰爻皆承五。九雲。中行無咎。泰二雲。得尚於中行。中行謂五。有孚中行者。言三與二四。同孚於五也。震為言。故為告。為王故為圭。坤為眾。故曰公。公共也。三震為諸侯。告公用圭者。言約同諸侯執圭。共往朝五也。圭者天子所錫子。今朝天子。故執以為信。舊解以凶事為兇喪。或為凶荒。則告之天子。告之友邦。而受其碑隧（左　）。告必將儀。或執壁。或用圭。如臧文仲以紀獻工告曜（左上入左下米）於齊。豈知告公用圭。即申有孚中行之義。與上之凶事無涉。是皆以他經例易。不知易文。上下旬。不必相屬也。</p><h3 id="象曰。益用凶事。固有之也。" tabindex="-1">象曰。益用凶事。固有之也。 <a class="header-anchor" href="#象曰。益用凶事。固有之也。" aria-label="Permalink to “象曰。益用凶事。固有之也。”">​</a></h3><p>言陰遇陰。陽遇陽。近而不相得故兇。乃易理當然之事。故曰固有。</p><p>六四。中行告公從。利用為依遷國。</p><p>中行謂五。震為告。坤為臣。為眾。從謂順五。告公從者。言下三陰宜共同承五也。坤為國。震動。故曰遷國。艮止故曰依。左傳隱六年。我周之東遷。晉鄭焉依。說文依椅也。利用為依遷國者。言坤國播遷。至五艮而止。依以建國也。陰從陽故利。巽為利也。</p><h3 id="象曰。告公從。以益志也。" tabindex="-1">象曰。告公從。以益志也。 <a class="header-anchor" href="#象曰。告公從。以益志也。" aria-label="Permalink to “象曰。告公從。以益志也。”">​</a></h3><p>坤為志。公從九五。陽益陰。故曰益志。自坤志象失傳。遂令某爻變成坎。以求志象矣。</p><p>九五。有孚惠心。勿問元吉。有孚惠我德。</p><p>爾雅釋言。惠順也。坤為順為心。有孚惠心。言五孚於下坤而順我也。震為問。五震覆。故曰勿問。五位尊。故曰元吉。勿問元吉者。言五乘重陰而大吉也。乾為德。有孚惠我德。言下三陰皆承順我而有軍也。</p><h3 id="象曰。有孚惠心。勿問之矣。惠我德。大得志也。" tabindex="-1">象曰。有孚惠心。勿問之矣。惠我德。大得志也。 <a class="header-anchor" href="#象曰。有孚惠心。勿問之矣。惠我德。大得志也。" aria-label="Permalink to “象曰。有孚惠心。勿問之矣。惠我德。大得志也。”">​</a></h3><p>坤為志。陽為大。陽五下乘重陰。故曰大得志。管子度地。天下之人皆歸其德而惠其義。注惠順也。正說此也。</p><p>上九。莫益之。或系之。立心勿恆。兇。</p><p>上與五為敵。故曰莫益。言益三也。上應在三。然上若益三。則為五所忌。而或系之。五艮體。艮為手為系也。坤為心，上應在坤。下虛。處巽上。風隕。進退不果。故曰立心勿恆。兇。恆九三雲。不恆其德。益上九與恆九三同為賣上。故亦曰勿恆。緣巽下撓。故義同也。</p><h3 id="象曰。莫益之。偏辭也。或系之。自外來也。" tabindex="-1">象曰。莫益之。偏辭也。或系之。自外來也。 <a class="header-anchor" href="#象曰。莫益之。偏辭也。或系之。自外來也。" aria-label="Permalink to “象曰。莫益之。偏辭也。或系之。自外來也。”">​</a></h3><p>恐其被系。戒以莫益。故曰偏辭。左傳襄三年。君子謂奚舉其偏而不嘗。注偏屬也。猶私也。外謂五。五為上敵。下系雲。幾易之情近而不相得則兇。或害之。故上欲應三。五或系之。五在外。言系之者仍在外也。同人九三曰敵剛。中孚六三雲。得敵。子夏傳。三與四為敵。是陽遇陽。陰遇陰。愈近而愈不相得。舊解自虞翻以來。皆不知此為周易根本定例。故說或系之。皆不知繫上九者為何爻。而無不誤矣。 按否泰者。天道之自然。為運會所必有。故以次於上經十卦之後。損益者人事之進退。為人為之所關。故以次於下經第十卦之後。十者數之終。終則變。變則否泰迭更。損益互見。此其義也。又損者泰之終。以見否泰雖屬無道。而由否而奉。由泰而否。損之益之。推輓之權。則在人為。有定而無定也。此上下經天人之分。動靜之別。非參育之聖人。固不能知其故也。故於上經之否泰。自為一卷。下經之損益。自為一卷。以見此四卦為全經之樞紐。與他卦絕不同也。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
